using Gtk 4.0;
using Adw 1;

template $EartagAlbumCoverButton: Adw.Bin {
  width-request: 196;
  height-request: 196;
  halign: center;
  valign: start;
  hexpand: false;
  vexpand: false;
  accessible-role: group;

  styles [
    "album-cover",
  ]

  Overlay drag_overlay {
    [overlay]
    Revealer highlight_revealer {
      receives-default: false;
      can-focus: false;
      can-target: false;
      reveal-child: false;
      transition-type: crossfade;
      hexpand: true;
      vexpand: true;

      Stack highlight_stack {
        Box hover_highlight {
          styles [
            "hover-highlight",
          ]

          Image {
            icon-name: "document-edit-symbolic";
            pixel-size: 48;
            valign: center;
            halign: center;
            hexpand: true;
            accessible-role: presentation;
          }
        }

        Box drop_highlight {
          styles [
            "drag-target",
          ]

          Image {
            icon-name: "document-send-symbolic";
            pixel-size: 48;
            valign: center;
            halign: center;
            hexpand: true;
          }
        }
      }
    }

    $EartagPopoverButton button {
      popover: "menu_popover";

      child: $EartagAlbumCoverImage cover_image {
        pixel-size: "196";
      };
    }
  }
}

menu options_menu {
  section {
    item {
      label: _("_Choose Image…");
      icon: "insert-image-symbolic";
      action: "albumcoverbutton.load";
    }

    item {
      label: _("_Save Image…");
      icon: "user-trash-symbolic";
      action: "albumcoverbutton.save";
    }

    item {
      label: _("_Remove Cover");
      icon: "user-trash-symbolic";
      action: "albumcoverbutton.remove";
    }
  }

  section {
    item {
      custom: "type_switcher";
    }
  }
}

PopoverMenu menu_popover {
  menu-model: options_menu;

  [type_switcher]
  Box cover_switch_box {
    hexpand: true;
    orientation: vertical;

    styles [
      "cover-switch-box",
    ]

    CheckButton front_toggle {
      label: _("Front");
      group: back_toggle;
    }

    CheckButton back_toggle {
      label: _("Back");
    }
  }
}

FileFilter image_file_filter {
  name: _("All supported image files");

  mime-types [
    // Supported natively by most formats:
    "image/jpg",
    "image/jpeg",
    "image/png",
    // Converted using Pillow:
    "image/bmp",
    "image/jp2",
    "image/webp",
  ]
}

using Gtk 4.0;

template $EartagAlbumCoverImage: Stack {
  hexpand: true;
  visible-child: no_cover;
  accessible-role: presentation;

  styles [
    "cover-image",
  ]

  Image no_cover {
    icon-name: "folder-music-symbolic";
    pixel-size: 96;
    halign: center;
    valign: center;
    accessible-role: presentation;
  }

  Image cover_image {
    hexpand: true;
    vexpand: true;
    pixel-size: 196;
    overflow: hidden;
    accessible-role: presentation;
  }
}

using Gtk 4.0;
using Adw 1;

template $EartagExtractTagsDialog: Adw.Dialog {
  title: _("Extract Tags from Filename");
  content-width: 600;
  content-height: 300;

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      show-end-title-buttons: false;
      show-start-title-buttons: false;

      [start]
      Button cancel_button {
        label: _("Cancel");
        focusable: true;
        clicked => $on_cancel();
      }

      [end]
      Button apply_button {
        label: _("Apply");
        focusable: true;
        clicked => $do_apply();

        styles [
          "suggested-action",
        ]
      }
    }

    Overlay {
      [overlay]
      ProgressBar rename_progress {
        valign: start;

        styles [
          "osd",
        ]
      }

      ScrolledWindow {
        Adw.Clamp content_clamp {
          Box {
            orientation: vertical;
            valign: center;
            vexpand: true;
            spacing: 12;
            margin-start: 12;
            margin-end: 12;
            margin-top: 12;
            margin-bottom: 24;

            ListBox {
              hexpand: true;
              valign: start;
              selection-mode: none;

              styles [
                "boxed-list",
              ]

              Adw.EntryRow preview_entry {
                title: _("Preview");
                editable: false;

                [suffix]
                $EartagPreviewSelectorButton preview_selector_button {}
              }
            }

            ListBox {
              hexpand: true;
              valign: start;
              selection-mode: none;

              styles [
                "boxed-list",
              ]

              Adw.EntryRow pattern_entry {
                title: _("Filename pattern");
                entry-activated => $do_apply();

                [suffix]
                $EartagTagSelectorButton tag_selector {
                  icon-name: "list-add-symbolic";
                  tooltip-text: _("Insert tag placeholder");
                  tag-selected => $add_tag_from_selector();

                  styles [
                    "flat",
                  ]
                }
              }

              Adw.SwitchRow toggle_strip_common_suffixes {
                title: _("Ignore common suffixes");
                subtitle: _("Automatically ignores ID suffixes often found in filenames of downloaded files. Disable this option if it interferes with your filenames.");
              }
            }
          }
        }
      }
    }
  };
}

using Gtk 4.0;

template $EartagFileListItem: Box {
  hexpand: true;
  spacing: 12;

  styles [
    "filelist-item",
  ]

  Stack cover_edit_stack {
    transition-type: crossfade;

    $EartagAlbumCoverImage coverart_image {
      pixel-size: "48";
      hexpand: "false";
    }

    CheckButton select_button {
      halign: center;

      styles [
        "selection-mode",
        "circular",
      ]
    }
  }

  Box data_box {
    orientation: vertical;
    hexpand: true;
    halign: fill;
    valign: center;
    spacing: 3;

    Box {
      Stack status_icon_stack {
        Image error_icon {
          icon-name: "dialog-warning-symbolic";
          tooltip-text: _("File has invalid values");
          visible: false;
          margin-end: 3;
        }

        Image modified_icon {
          icon-name: "file-modified-symbolic";
          tooltip-text: _("File has unsaved changes");
          visible: false;
          margin-end: 3;
        }
      }

      Label title_label {
        halign: start;
        hexpand: true;
        ellipsize: middle;

        styles [
          "heading",
        ]
      }
    }

    Label filename_label {
      halign: start;
      hexpand: true;
      ellipsize: middle;

      styles [
        "subtitle",
      ]
    }
  }

  Box suffixes {
    spacing: 6;

    Button remove_button {
      icon-name: "edit-delete-symbolic";
      clicked => $remove_item();
      hexpand: true;
      halign: end;
      valign: center;
      tooltip-text: _("Remove from list");

      styles [
        "flat",
        "circular",
      ]
    }
  }
}

using Gtk 4.0;
using Adw 1;

template $EartagFilenameRow: Adw.EntryRow {
  title: _("Filename");
  show-apply-button: true;
  apply => $set_filename();
}

using Gtk 4.0;
using Adw 1;

template $EartagFileView: Stack {
  transition-type: none;

  Adw.StatusPage loading {
    icon-name: "content-loading-symbolic";
    title: _("Loading Files…");
  }

  Stack content_stack {
    transition-type: none;

    Adw.StatusPage select_file {
      icon-name: "edit-select-all-symbolic";
      title: _("Select a File");
      description: _("Select the files you want to edit from the list of opened files.");
    }

    ScrolledWindow content_scroll {
      hscrollbar-policy: never;
      hexpand: true;
      vexpand: true;

      Adw.Clamp content_clamp {
        maximum-size: 576;

        Box {
          orientation: vertical;
          hexpand: true;
          spacing: 24;
          margin-top: 36;
          margin-bottom: 24;
          margin-start: 12;
          margin-end: 12;

          Overlay cover_overlay {
            $EartagAlbumCoverButton album_cover {}

            [overlay]
            Revealer previous_file_button_revealer {
              halign: start;
              valign: center;
              reveal-child: false;
              transition-type: crossfade;

              styles [
                "prev-next-button-container",
              ]

              Button previous_file_button {
                tooltip-text: _("Previous file");
                icon-name: "go-previous-symbolic";

                styles [
                  "osd",
                  "prev-next-button",
                ]
              }
            }

            [overlay]
            Revealer next_file_button_revealer {
              halign: end;
              valign: center;
              reveal-child: false;
              transition-type: crossfade;

              styles [
                "prev-next-button-container",
              ]

              Button next_file_button {
                tooltip-text: _("Next file");
                icon-name: "go-next-symbolic";

                styles [
                  "osd",
                ]
              }
            }
          }

          Box important_data_container {
            orientation: vertical;
            spacing: 6;

            $EartagTagEditableLabel title_entry {
              title: _("Title");
              bound-property: "title";
              margin-start: "12";
              margin-end: "12";

              styles [
                "title-1",
              ]
            }

            $EartagTagEditableLabel artist_entry {
              title: _("Artist");
              bound-property: "artist";
              margin-start: "12";
              margin-end: "12";

              styles [
                "title-3",
                "artist",
              ]
            }

            $EartagFileInfoLabel file_info {
              justify: "center";
              wrap: "true";
              margin-top: "6";

              styles [
                "caption-header",
              ]
            }
          }

          Box {
            orientation: vertical;
            spacing: 6;

            Box tracknumber_box {
              spacing: 6;
              hexpand: true;
              accessible-role: list;

              $EartagTagEntryRow tracknumber_entry {
                title: _("Track number");
                bound-property: "tracknumber";
                max-width-chars: "4";
                is-numeric: "true";
                hexpand: "true";

                styles [
                  "card",
                  "tagentry-small",
                ]
              }

              $EartagTagEntryRow totaltracknumber_entry {
                title: _("Total tracks");
                bound-property: "totaltracknumber";
                max-width-chars: "4";
                is-numeric: "true";
                hexpand: "true";

                styles [
                  "card",
                  "tagentry-small",
                ]
              }
            }

            ListBox tag_list {
              hexpand: true;
              valign: start;
              selection-mode: none;

              styles [
                "boxed-list",
              ]

              $EartagTagEntryRow album_entry {
                title: _("Album");
                bound-property: "album";
              }

              $EartagTagEntryRow albumartist_entry {
                title: _("Album artist");
                bound-property: "albumartist";
              }

              $EartagTagEntryRow genre_entry {
                title: _("Genre");
                bound-property: "genre";
              }

              $EartagTagEntryRow releasedate_entry {
                title: _("Release date");
                bound-property: "releasedate";
                is-date: "true";
              }

              $EartagTagEntryRow comment_entry {
                title: _("Comment");
                bound-property: "comment";
              }
            }

            ListBox filename_listbox {
              hexpand: true;
              valign: start;
              selection-mode: none;

              styles [
                "boxed-list",
              ]

              $EartagFilenameRow filename_entry {}
            }

            $EartagMoreTagsGroup more_tags_group {}
          }
        }
      }
    }
  }
}

using Gtk 4.0;

template $EartagMoreTagsGroup: Box {
  orientation: vertical;
  spacing: 6;

  ListBox tag_entry_listbox {
    hexpand: true;
    valign: start;
    selection-mode: none;

    styles [
      "boxed-list",
    ]
  }

  $EartagTagSelectorButton tag_selector {
    label: _("Add tag");
    tag-selected => $add_row_from_selector();
    halign: "center";
    margin-top: "6";

    styles [
      "raised",
      "pill",
    ]
  }
}

using Gtk 4.0;
using Adw 1;

template $EartagNoFile: Adw.Bin {
  WindowHandle {
    hexpand: true;
    vexpand: true;

    Adw.StatusPage nofile_status {
      icon-name: "app.drey.EarTag";
      title: _("Ear Tag");
      description: _("Open or drag in some audio files to edit their metadata.");

      styles [
        "nofiles",
      ]

      Box {
        orientation: vertical;
        halign: center;
        spacing: 12;

        Button open_file {
          label: _("Open File");
          halign: center;
          focusable: true;
          clicked => $on_add_file();

          styles [
            "suggested-action",
            "pill",
          ]
        }

        Button open_folder {
          label: _("Open Folder");
          halign: center;
          clicked => $on_add_folder();

          styles [
            "pill",
          ]
        }

        CheckButton open_recursive {
          label: _("Include Files from Subfolders");
          tooltip-text: _("When opening a folder, include files from its subfolders");

          styles [
            "subtitle"
          ]
        }
      }
    }
  }
}
SizeGroup {
  widgets [
    open_file,
    open_folder
  ]
}

using Gtk 4.0;

template $EartagPreviewSelectorButton: MenuButton {
  tooltip-text: _("Select file to preview");
  valign: center;

  styles [
    "flat",
  ]

  popover: Popover popover {
    autohide: true;

    styles [
      "menu",
    ]

    Box {
      orientation: vertical;

      SearchEntry search_entry {
        margin-top: 6;
        margin-start: 6;
        margin-end: 6;
        placeholder-text: _("Search by title, artist, filename…");
      }

      ScrolledWindow {
        hscrollbar-policy: never;
        vscrollbar-policy: automatic;
        propagate-natural-width: true;
        propagate-natural-height: true;

        ListView list {
          single-click-activate: true;
        }
      }
    }
  };
}

using Gtk 4.0;

template $EartagPreviewSelectorItem: Box {
  orientation: vertical;

  Label formatted_path_label {
    halign: start;
    hexpand: true;
    ellipsize: middle;
  }

  Label filename_label {
    halign: start;
    hexpand: true;
    ellipsize: middle;

    styles [
      "subtitle",
    ]
  }
}

using Gtk 4.0;
using Adw 1;

template $EartagRenameDialog: Adw.Dialog {
  title: _("Rename Selected Files");
  content-width: 600;
  content-height: 300;

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      show-end-title-buttons: false;
      show-start-title-buttons: false;

      [start]
      Button cancel_button {
        label: _("Cancel");
        focusable: true;
        clicked => $on_cancel();
      }

      [end]
      Button rename_button {
        label: _("Rename");
        focusable: true;
        clicked => $do_rename();

        styles [
          "suggested-action",
        ]
      }
    }

    content: Adw.ToastOverlay toast_overlay {
      Overlay {
        [overlay]
        ProgressBar rename_progress {
          valign: start;

          styles [
            "osd",
          ]
        }

        Box {
          orientation: vertical;

          Adw.Banner sandbox_warning_banner {
            title: _("Ear Tag needs additional permissions to rename files in-place.");
            button-label: _("Learn More");
            button-clicked => $on_sandbox_warning_learn_more();

            styles [
              "warning",
            ]
          }

          Adw.Banner error_banner {
            title: _("Failed to rename files. Check the logs for more information.");

            styles [
              "error",
            ]
          }

          ScrolledWindow {
            Adw.Clamp {
              Box {
                orientation: vertical;
                valign: center;
                vexpand: true;
                spacing: 12;
                margin-start: 12;
                margin-end: 12;
                margin-top: 12;
                margin-bottom: 24;

                ListBox {
                  hexpand: true;
                  valign: start;
                  selection-mode: none;

                  styles [
                    "boxed-list",
                  ]

                  Adw.EntryRow preview_entry {
                    title: _("Preview");
                    editable: false;

                    [suffix]
                    $EartagPreviewSelectorButton preview_selector_button {}
                  }
                }

                Adw.PreferencesGroup {
                  Adw.EntryRow filename_entry {
                    title: _("Filename pattern");
                    changed => $update_preview();
                    entry-activated => $do_rename();

                    [suffix]
                    $EartagTagSelectorButton tag_selector {
                      icon-name: "list-add-symbolic";
                      tooltip-text: _("Insert tag placeholder");
                      tag-selected => $add_placeholder_from_selector();

                      styles [
                        "flat",
                      ]
                    }
                  }

                  Adw.ActionRow folder_selector_row {
                    title: _("Move to folder");

                    [suffix]
                    Button folder_selector_button {
                      icon-name: "folder-open-symbolic";
                      tooltip-text: _("Select a folder…");
                      valign: center;
                      clicked => $show_folder_selector();

                      styles [
                        "flat",
                      ]
                    }

                    [suffix]
                    Button folder_remove_button {
                      icon-name: "edit-delete-symbolic";
                      tooltip-text: _("Unselect folder");
                      valign: center;
                      sensitive: false;
                      clicked => $remove_folder();

                      styles [
                        "flat",
                      ]
                    }
                  }
                }

                Label {
                  wrap: true;
                  use-markup: true;
                  justify: center;
                  label: _("For a list of available placeholders, see the <a href=\"https://gitlab.gnome.org/World/eartag/-/blob/main/src/backends/README.md#available-tags\">list of available tags</a>.");

                  styles [
                    "dim-label",
                  ]
                }
              }
            }
          }
        }
      }
    };
  };
}

using Gtk 4.0;
using Adw 1;

template $EartagPreferencesDialog: Adw.PreferencesDialog {
  Adw.PreferencesPage {
    Adw.PreferencesGroup {
      title: _("General");

      Adw.SwitchRow open_folders_recursively_toggle {
        title: _("Search for files in subfolders");
        subtitle: _("When opening a folder, include files from its subfolders");
      }
    }

    Adw.PreferencesGroup {
      title: _("File identification");

      Adw.SpinRow mb_confidence_spinbutton {
        title: _("MusicBrainz confidence treshold");
        subtitle: _("Minimum confidence percentage required for a MusicBrainz search result to be evaluated");

        adjustment: Adjustment {
          lower: 0;
          upper: 100;
          value: 50;
          page-increment: 10;
          step-increment: 1;
        };
      }

      Adw.SpinRow aid_confidence_spinbutton {
        title: _("AcoustID confidence treshold");
        subtitle: _("Minimum confidence percentage required for an AcoustID lookup result to be evaluated");

        adjustment: Adjustment {
          lower: 0;
          upper: 100;
          value: 50;
          page-increment: 10;
          step-increment: 1;
        };
      }

      Adw.ComboRow cover_size_comborow {
        title: _("Downloaded cover art size");

        model: StringList {
          strings [
            _("Do not download covers"),
            _("250 px"),
            _("500 px"),
            _("1200 px"),
            _("Maximum size"),
          ]
        };
      }
    }
  }
}

using Gtk 4.0;
using Adw 1;

